import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import api from '../api/axios';
import { Container, Table, Spinner, Alert } from 'react-bootstrap';

const Progress = () => {
  const [grades, setGrades] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const roles = useSelector(state => state.auth.roles || []);
  const user = useSelector(state => state.auth.user);

  useEffect(() => {
    fetchGrades();
  }, []);

  const fetchGrades = async () => {
    setLoading(true);
    try {
      const res = await api.get('/progress');
      setGrades(res.data);
    } catch (err) {
      setError(err.response?.data?.error || 'Ошибка загрузки успеваемости');
    } finally {
      setLoading(false);
    }
  };

  const isStudent = roles.includes('Ученик');

  if (loading) {
    return (
      <Container className="text-center mt-5">
        <Spinner animation="border" variant="primary" />
        <p>Загрузка успеваемости...</p>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="mt-4">
        <h3>Успеваемость</h3>
        <Alert variant="danger">{error}</Alert>
      </Container>
    );
  }

  return (
    <Container className="mt-4">
      <h3>Успеваемость</h3>
      {!isStudent && (
        <p className="text-muted">Просмотр успеваемости ученика</p>
      )}
      
      {grades.length === 0 ? (
        <Alert variant="info">Нет оценок</Alert>
      ) : (
        <Table striped bordered hover responsive>
          <thead>
            <tr>
              <th>Предмет</th>
              <th>1 четверть</th>
              <th>2 четверть</th>
              <th>3 четверть</th>
              <th>4 четверть</th>
              <th>Годовая</th>
              <th>Экзамен</th>
              <th>Итоговая</th>
            </tr>
          </thead>
          <tbody>
            {grades.map(subj => (
              <tr key={subj.subject_id}>
                <td><strong>{subj.subject_name}</strong></td>
                <td>{subj.q1 || '—'}</td>
                <td>{subj.q2 || '—'}</td>
                <td>{subj.q3 || '—'}</td>
                <td>{subj.q4 || '—'}</td>
                <td>{subj.year_grade || '—'}</td>
                <td>{subj.exam_grade || '—'}</td>
                <td>{subj.final_grade || '—'}</td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
    </Container>
  );
};

export default Progress;
